import java.util.ArrayList;

public class ListRotatorTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        ArrayList<Integer> nums = new ArrayList<>(java.util.List.of(1, 2, 3, 4, 5));
        String before = nums.toString();
        try {
            check("rotated by 2", "[3, 4, 5, 1, 2]", String.valueOf(ListRotator.rotated(nums, 2)));
            check("original list unchanged", before, nums.toString());
            check("rotated by 0", "[1, 2, 3, 4, 5]", String.valueOf(ListRotator.rotated(nums, 0)));
            check("rotated by size (full circle)", "[1, 2, 3, 4, 5]", String.valueOf(ListRotator.rotated(nums, 5)));
            check("rotated by 7 wraps like 2", "[3, 4, 5, 1, 2]", String.valueOf(ListRotator.rotated(nums, 7)));
            check("single element", "[9]", String.valueOf(ListRotator.rotated(new ArrayList<>(java.util.List.of(9)), 4)));
            check("empty list", "[]", String.valueOf(ListRotator.rotated(new ArrayList<>(), 3)));
        } catch (Exception e) {
            System.out.println("FAIL  unexpected exception: " + e);
            failures++;
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

