import java.util.ArrayList;

public class ListRotator {

    public static ArrayList<Integer> rotated(ArrayList<Integer> list, int k) {
        ArrayList<Integer> result = new ArrayList<>();
        if (list.isEmpty()) {
            return result;
        }
        int shift = k % list.size();
        for (int i = 0; i < list.size(); i++) {
            result.add(list.get((i + shift) % list.size()));
        }
        return result;
    }
}
